  str_n12_affix_des_5122313 = "A habilidade de Phorosion Back Attack obteve um novo efeito: Transforme as telhas ao redor dos Aurorianos em telhas bloqueadas e seu coeficiente DMG +10%",
  str_n12_affix_des_5122314 = "Para cada Lumiwall morto, todos os outros inimigos no campo restauram seu próprio HP <color=#00F6FF>10%</color> de seu HP Máximo.",
  str_n12_affix_des_5122315 = "Para cada Lumiwall morto, todos os outros inimigos no campo restauram seu próprio HP <color=#00F6FF>25%</color> de seu HP máximo.",
  str_n12_affix_des_5122316 = "Para cada Lumiwall morto, todos os outros inimigos no campo restauram seu próprio HP <color=#00F6FF>50%</color> de seu HP Máximo.",
  str_n12_affix_des_5122317 = "Forosion obteve Pranayama I: No início de cada rodada, atualize <color=#00F6FF>1</color> pilha de Escudo de Conde. Se o escudo de contagem durar até o final da rodada, restaure HP <color=#00F6FF>3%</color>",
  str_n12_affix_des_5122318 = "Forosion obteve Pranayama II: No início de cada rodada, atualize <color=#00F6FF>3</color> pilhas de Escudo de Conde. Se houver algum escudo de contagem no final da rodada, restaure o HP <color=#00F6FF>3%</color>",
  str_n12_affix_des_5122319 = "Forosion obteve Pranayama III: No início de cada rodada, atualize <color=#00F6FF>5</color> pilhas de Escudo de Conde. Se houver algum escudo de contagem no final da rodada, restaure o HP <color=#00F6FF>5%</color>",
  str_n12_affix_des_5122320 = "Forosion obtido Dreno de Vida I: Converter <color=#00F6FF>100%</color> do dano que causa ao seu HP.",
  str_n12_affix_des_5122321 = "Forosion obtido Dreno de Vida II: Converter <color=#00F6FF>200%</color> do dano que causa ao seu HP.",
  str_n12_affix_des_5122322 = "Forosion obtido Dreno de Vida III: Converter <color=#00F6FF>400%</color> do dano que causa ao seu HP.",
  str_n12_affix_des_5122323 = "Forosion obtido Fraqueza Invisível: Reduza o dano que sofre de Chain Combos. Quanto mais próximo estiver dos Aurorianos, melhor será o efeito de redução. Até 60% de dano pode ser reduzido quando estiver ao lado de Aurorianos.",
  str_n12_affix_des_5122324 = "Escudo de Movimento obtido por Forosion: Para cada bloco que os Aurorianos movem, ganhe 1 pilha de marca de aumento de DEF, que pode aumentar a DEF base em 5%. Todas as pilhas são limpas no final de cada rodada.",
  str_n12_affix_des_5122401 = "ATK do Formless -<color=#00F6FF>15%</color> e DEF -<color=#00F6FF>30%</color>",
  str_n12_affix_des_5122402 = "O dano que o Formless sofre do ataque normal, Chain Combos e Active Skills -<color=#00F6FF>{1}%</color>",
  str_n12_affix_des_5122405 = "ATK de Nonentity +<color=#00F6FF>{1}%</color>, e DEF e Max HP +<color=#00F6FF>{2}%</color>",
  str_n12_affix_des_5122408 = "Obtido sem forma <color=#00F6FF>Ressuscitação I</color>: Torne-se invencível quando seu HP cair para 1% e restaure <color=#00F6FF>10%</color> de seu HP máximo depois.",
  str_n12_affix_des_5122409 = "Obtido sem forma <color=#00F6FF>Ressuscitação II</color>: Torne-se invencível quando seu HP cair para 1% e restaure <color=#00F6FF>25%</color> de seu HP máximo depois.",
  str_n12_affix_des_5122410 = "Obtido sem forma <color=#00F6FF>Ressuscitação III</color>: Torne-se invencível quando seu HP cair para 1% e restaure <color=#00F6FF>40%</color> de seu HP máximo depois.",
  str_n12_affix_des_5122411 = "O dano de Formless causado a Aurorians aumenta em porcentagem de acordo com o HP atual do alvo. Quanto menor o HP de um auroriano, maior o DMG, até <color=#00F6FF>{1}</color> vezes do DMG original.",
  str_n12_affix_des_5122413 = "A ordem do grupo de habilidades do Formless mudou: Nonentity Feast é liberado durante a primeira rodada",
  str_n12_affix_des_5122414 = "Formless junta-se à batalha com <color=#00F6FF>{1}</color> pilhas de escudo de contagem.",
  str_n12_affix_des_5122417 = "A habilidade Flash invisível do Formless ganhou um novo efeito: Invoque um Abismo adicional em um local aleatório dentro de 1 aglomerado ao redor dos Aurorianos.",
  str_n12_affix_des_5122418 = "O Auroriano na posição de Capitão não pode atacar a não ser em uma peça de seu elemento.",
  str_n12_affix_des_5122419 = "Obtido sem forma <color=#00F6FF>Sem danos I</color>: Quando o dano de um único ataque excede seu HP máximo em <color=#00F6FF>15%</color>, o dano excedente é ignorado.",
  str_n12_affix_des_5122420 = "Obtido sem forma <color=#00F6FF>Sem danos II</color>: Quando o dano de um único ataque excede seu HP máximo em <color=#00F6FF>12%</color>, o dano excedente é ignorado.",
  str_n12_affix_des_5122421 = "Obtido sem forma <color=#00F6FF>Livre de danos III</color>: Quando o dano de um único ataque excede seu HP máximo em <color=#00F6FF>8%</color>, o dano excedente é ignorado.",
  str_n12_affix_des_5122422 = "Obtido sem forma <color=#00F6FF>Casca dura I</color>: Apenas o primeiro <color=#00F6FF>15</color> ataques normais podem causar danos.",
  str_n12_affix_des_5122423 = "Obtido sem forma <color=#00F6FF>Hard Shell II</color>: Apenas o primeiro <color=#00F6FF>10</color> ataques normais podem causar danos.",
  str_n12_affix_des_5122424 = "Obtido sem forma <color=#00F6FF>Casca Rígida III</color>: Apenas o primeiro <color=#00F6FF>7</color> ataques normais podem causar danos.",
  str_n12_affix_des_5122425 = "Obtido sem forma <color=#00F6FF>Fragilidade I</color>: O DMG de Queima Sustentada, Envenenado e Sangramento é aumentado para <color=#00F6FF>2</color> vezes o valor normal.",
  str_n12_affix_des_5122426 = "Obtido sem forma <color=#00F6FF>Fragilidade II</color>: O DMG de Queima Sustentada, Envenenado e Sangramento é aumentado para <color=#00F6FF>3</color> vezes o valor normal.",
  str_n12_affix_des_5122427 = "obtido sem forma <color=#00F6FF>Aurora Eco</color>: Durante o Aurora Time, seu HP é restaurado ao que era no início da rodada.",
  str_n12_affix_des_10101 = "DEF e HP máximo dos jogadores de boliche -<color=#00F6FF>{1}%</color>",
  str_n12_affix_des_10102 = "O dano que os jogadores de boliche recebem dos combos em cadeia é <color=#00F6FF>1,5</color> vezes a quantidade normal.",
  str_n12_affix_des_10103 = "HP máximo dos jogadores de boliche +<color=#00F6FF>{1}%</color>",
  str_n12_affix_des_10104 = "DEF e HP máximo de todos os Thumpers +<color=#00F6FF>{1}%</color>",
  str_n12_affix_des_11104 = "DEF e HP máximo de todos os Thumpers +<color=#00F6FF>{1}%</color>, e Mobilidade +1.",
  str_n12_affix_des_10105 = "Deathrider causa dano adicional de <color=#00F6FF>{1}%</color> do HP Máximo para Aurorianos.",
  str_n12_affix_des_10601 = "Crie 2 armadilhas extras do Gerador de Bombas",
  str_n12_affix_des_10701 = "No início da batalha, solte um Thumper que não pode ser atacado.",
  str_n12_affix_des_10801 = "O dano que os jogadores de boliche sofrem do ataque normal, combo e habilidades ativas em seu estado sóbrio é reduzido em <color=#00F6FF>{1}%</color>",
  str_n12_affix_des_10901 = "Os jogadores de boliche são imunes ao efeito Amedrontado.",
  str_n12_affix_des_11001 = "Os jogadores de boliche obtiveram o Aprimoramento I: No estado normal, aumente o ATK de outros inimigos em <color=#00F6FF>3%</color> e Mobilidade por <color=#00F6FF>1</color> ponto. Não acumulável com outros efeitos do mesmo tipo.",
  str_n12_affix_des_11002 = "Os jogadores de boliche obtiveram o Aprimoramento II: Em estado normal, aumente o ATK de outros inimigos em <color=#00F6FF>6%</color> e Mobilidade por <color=#00F6FF>1</color> ponto. Não acumulável com outros efeitos do mesmo tipo.",
  str_n12_affix_des_11003 = "Os jogadores de boliche obtiveram o Aprimoramento III: No estado normal, aumente o ATK de outros inimigos em <color=#00F6FF>5%</color> e Mobilidade por <color=#00F6FF>2</color> ponto. Não acumulável com outros efeitos do mesmo tipo.",
  str_n12_affix_des_11101 = "Bowlingers obtiveram Valliance I: Sua DEF aumenta à medida que seu HP cai para até <color=#00F6FF>1.5</color> vezes do seu DEF original.",
  str_n12_affix_des_11102 = "Bowlingers obtiveram Valliance II: Sua DEF aumenta à medida que seu HP cai para até <color=#00F6FF>2</color> vezes do seu DEF original.",
  str_n12_affix_des_11103 = "Bowlingers obtiveram Valliance III: Sua DEF aumenta à medida que seu HP cai para até <color=#00F6FF>2.5</color> vezes do seu DEF original.",
  str_n12_affix_des_11201 = "Bowlinger 680 obteve Dark Domain: Em seu estado sóbrio, perde 1 rodada extra no final da rodada",
  str_n12_affix_des_11301 = "Bowlingers obtém Lingering Darkflow: Em seu estado normal, eles podem causar danos ao Time ao se moverem dentro de 1 grupo ao redor deles",
  str_n12_affix_des_51225011 = "ATK de Valência -<color=#00F6FF>{1}%</color> e DEF -<color=#00F6FF>{2}%</color>.",
  str_n12_affix_des_51225021 = "ATK do Canhão Laser I -<color=#00F6FF>{1}%</color>.",
  str_n12_affix_des_51225031 = "HP máximo de Valência +<color=#00F6FF>{1}%</color>",
  str_n12_affix_des_51225061 = "O dano que Valencia sofre com o ataque normal -<color=#00F6FF>{1}%</color>.",
  str_n12_affix_des_51225091 = "Canhão Laser I atualizado para Canhão Laser II: Causa dano e inflige 2 pilhas de efeito Burning",
  str_n12_affix_des_51225101 = "Dragger I atualizado para Dragger II: Esta armadilha é ativada novamente depois que todas as outras armadilhas completam sua ação",
  str_n12_affix_des_51225111 = "Prism Tower I atualizado para Prism Tower II: Os raios laser são emitidos na forma de uma Union Jack.",
  str_n12_affix_des_51225121 = "Jammer I atualizado para Jammer II: afeta uma área maior. Todas as peças dentro de seu alcance estão bloqueadas",
  str_n12_affix_des_51325131 = "HP da Torre Prisma +<color=#00F6FF>{1}</color>",
  str_n12_affix_des_51325141 = "O dano de Valência causado aos Aurorianos aumenta em porcentagem de acordo com o HP atual do alvo. Quanto menor o HP de um auroriano, maior o DMG, até <color=#00F6FF>{1}</color> vezes do DMG original.",
  str_n12_affix_des_51325161 = "O dano de Valência causado aos Aurorianos aumenta em porcentagem de acordo com o HP atual do alvo. Quanto menor o HP de um auroriano, maior o DMG, até <color=#00F6FF>{1}</color> vezes do DMG original. Além disso, a mobilidade de Valência +<color=#00F6FF>{2}</color>",
  str_n12_affix_des_51325171 = "A condição de ativação para todos os Aurorianos' Chain Combo +<color=#00F6FF>{1}</color>.",
  str_n12_affix_des_51325181 = "Valencia obteve Tenacidade I: Receber <color=#00F6FF>3</color> pilhas da marca de diminuição de DANO por rodada, cada pilha reduzindo o DANO de todos os tipos em <color=#00F6FF>10%</color>. <color=#00F6FF>1</color> pilha da marca desaparece toda vez que ela sofre dano.",
  str_n12_affix_des_51325191 = "Valencia obteve Tenacity II: Receba <color=#00F6FF>5</color> pilhas da marca de diminuição de DANO por rodada, cada pilha reduzindo o DANO de todos os tipos em <color=#00F6FF>7%</color>. <color=#00F6FF>1</color> pilha da marca desaparece toda vez que ela sofre dano.",
  str_n12_affix_des_51325201 = "Valencia obteve Tenacity III: Receba <color=#00F6FF>7</color> pilhas da marca de diminuição de DANO por rodada, cada pilha reduzindo o DANO de todos os tipos em <color=#00F6FF>6%</color>. <color=#00F6FF>1</color> pilha da marca desaparece toda vez que ela sofre dano.",
  str_n12_affix_des_51325211 = "Valencia obteve Escudo Negro I: Receber <color=#00F6FF>3</color> pilhas de escudo de contagem assim que o Aurora Time começar. O escudo desaparece no final do Aurora Time.",
  str_n12_affix_des_51325221 = "Valencia obteve Escudo Negro II: Receba <color=#00F6FF>8</color> pilhas de escudo de contagem assim que o Aurora Time começar. O escudo desaparece no final do Aurora Time.",
  str_n12_affix_des_51325231 = "Valencia obteve Escudo Negro III: Receba <color=#00F6FF>12</color> pilhas de escudo de contagem assim que o Aurora Time começar. O escudo desaparece no final do Aurora Time.",
