  str_n12_mission_sidename_17 = "Ligar",
  str_n12_mission_sidename_18 = "Intercapítulo",
  str_n12_1_desc_long = "O Colosso recebeu um sinal estranho. Ao tentar descobrir a fonte do sinal, o grupo caiu em um espaço incrível.",
  str_n12_2_desc_long = "Era uma cidade extraordinária com alguns guardas robôs ativos.\nSiobhan, um estudioso da Illumina, sugeriu vestir um uniforme especial para evitar que os robôs atacassem.",
  str_n12_3_desc_long = "Você conheceu os companheiros de Siobhan, Florine e Erica de Lumópolis.\nEsses dois membros da Divisão de Investigação de Hereges de Lumopolis pareciam ter objetivos próprios.\nUma Equipe de Exploração ad hoc foi formada...",
  str_n12_4_desc_long = "As informações foram compartilhadas entre o grupo. Ficou claro que o lugar era uma cidade antiga em funcionamento.\nDe alguma forma, havia cortado completamente o contato com o mundo exterior e era bem mantido por várias máquinas.\nDo outro lado, duas figuras misteriosas observavam a festa no escuro...",
  str_n12_5_desc_long = "Enquanto você rastreava a misteriosa fonte de sinal, o chão começou a tremer novamente e mais inimigos estavam se aproximando.\nPara surpresa de todos, surgiram duas donzelas estranhas.\nQuem eram eles?",
  str_n12_6_desc_long = "As duas meninas eram filhas do Explorador Seamus de Illumina?\nInfelizmente, Seamus parecia ter falecido.\nAntes que você pudesse saber mais, uma IA chamada Butler apareceu, aconselhando o grupo a se afastar de perigos potenciais...",
  str_n12_7_desc_long = "O mordomo levou o grupo a um distrito fabril relativamente seguro. Valencia apresentou brevemente sua invejável vida totalmente automática.\nO avanço precipitado de Erica agravou a desconfiança de Gretel no grupo. Ela saiu com Valência.",
  str_n12_8_desc_long = "Depois de repelir alguns Eclipsites agressivos, Vice recebeu outra mensagem criptografada da transmissão de Seamus.\nO partido teve uma ideia melhor da situação e decodificou um conjunto de coordenadas de sua mensagem.\nDevemos nos encontrar com os outros o mais rápido possível e seguir juntos para o novo destino!",
  str_n12_9_desc_long = "Você salvou dois aurorianos - Ruby e Rouge, membros da Rediesel Wrench.\nEles revelaram que você estava sob a terra e que o céu acima não era real.\nRuby entregou a você um comunicador para que você pudesse manter contato e decolou com Rouge.",
  str_n12_10_desc_long = "Perto do destino, você sentiu que um bom número de Eclipsites se aproximava de Valência e Gretel.\nSiobhan e Florine decidiu vir em socorro das irmãs. O resto do grupo continuou em direção às coordenadas.\nAs duas irmãs já estavam em uma dura batalha. Quando o Butler estava lutando para resistir aos Eclipsites, o poderoso Lumina de Gretel explodiu.",
  str_n12_11_desc_long = "Depois de receber Ruby e o pedido de socorro de Rouge, o grupo se encontrou com sucesso e foi para as coordenadas deixadas por Seamus.\nEra o quarto do Sr. e Sra. Seamus, onde alguns de seus registros criptografados eram mantidos.\nAlém disso, você descobriu um cão robótico interessante.",
  str_n12_12_desc_long = "Quando todos vocês estavam ocupados vasculhando o quarto de Seamus, Valencia e Gretel apareceram.\nAs irmãs enfurecidas ordenaram que os dróides o atacassem. Surpreendentemente, até mesmo Eclipsites obedeceu ao seu comando.\nFelizmente, a cidade estava tremendo novamente, o que pareceu afetar Gretel. Você aproveitou esta oportunidade para escapar.",
  str_n12_13_desc_long = "Tendo escapado da ira de Valencia e Gretel, Siobhan conseguiu decifrar o registro de Seamus.\nRegistrava sua chegada a esta cidade e sua vida com o Mordomo.\nA pista final surgiu: a única saída era através do núcleo de energia nas profundezas da cidade!",
  str_n12_14_desc_long = "O grupo se separou. Florine e alguns outros foram à frente para verificar a liderança enquanto Siobhan voltou atrás com você.\nEla não podia deixar Valencia e Gretel para trás nesta cidade em colapso.",
  str_n12_15_desc_long = "Valencia estava cética em relação à sua história, enquanto Gretel permaneceu extremamente hostil com os estranhos.\nSeu ataque foi resistido, o que a levou à beira de um colapso mais uma vez. A cidade inteira começou a tremer...",
  str_n12_16_desc_long = "Valencia o impediu de se aproximar da Gretel desmoronada e uma batalha feroz se seguiu.\nEventualmente, Siobhan convenceu Valencia a ler a carta que Seamus havia deixado para ela.\nDepois de ler as últimas palavras de seu pai, Valencia finalmente baixou a guarda e aceitou sua oferta de ajuda.\nNo entanto, Gretel e o Mordomo escaparam enquanto você conversava com Valencia...",
  str_n12_17_desc_long = "Todo o grupo prometeu ajudar Gretel. Valencia concordou em participar.\nVocê chegou ao local-alvo nas profundezas da cidade, e a unidade de Florine já havia entrado.\nGretel provavelmente também estava lá embaixo, tentando proteger o núcleo de energia nessa situação precária.\nComo o resto da história se desenrolaria? Continua.",
  str_n12_18_desc_long = "Em meio a outro terremoto, você caiu no escuro e estabeleceu telepatia inesperada com o Mordomo.\nEle respondeu a muitas perguntas suas antes de mencionar uma IA preocupante, Abby.",
  str_n12_intro_head_1 = "Obtendo reputação de investigação:",
  str_n12_intro_head_2 = "Descrição da expedição diária:",
  str_n12_intro_head_3 = "Descrição da Zona de Perigo:",
  str_n12_intro_body_1 = "1. Durante o evento, completando as etapas da Expedição Diária e atendendo aos requisitos de pontos nas Missões de Desafio da Zona de Perigo para obter Reputação de Investigação.\n2. Reputação de Investigação Obtida pode ser usada para desbloquear recompensas de Notas de Investigação e histórias de eventos.",
  str_n12_intro_body_2 = "1. Os estágios da Expedição Diária são divididos em 3 dificuldades e os monstros são atualizados diariamente. Completar com sucesso os estágios concede item de evento—Reputação de Investigação de acordo com a dificuldade. Depois de concluído, os navegadores podem tentar o mesmo desafio novamente para ganhar mais reputação de investigação até que o limite diário seja atingido.\n2. Os navegadores começarão com um limite padrão de 2.000 Reputação de Investigação, seguido por um aumento de 2.000 a cada dia até que o limite máximo de 16.000 seja atingido.",
  str_n12_intro_body_3 = "1. Existem 5 conjuntos de fases da Zona de Perigo, e os conjuntos serão desbloqueados em sequência todos os dias. Uma vez que os estágios são desbloqueados, os navegadores são livres para selecionar o nível de dificuldade e os atributos para o desafio. Diferentes combinações de níveis de dificuldade e atributos determinarão a experiência de batalha e a pontuação dos navegadores.\n2. Os 5 conjuntos de estágios podem ser desafiados repetidamente assim que forem desbloqueados, e a pontuação mais alta será calculada separadamente e não será atualizada. As pontuações estão relacionadas às missões de desafio em cada Zona de Perigo e com base na pontuação de liberação mais alta de cada nível. Os navegadores que completarem as Missões de Desafio especificadas receberão a Reputação de Investigação correspondente.",
  str_n12_entrust_stage_intro_title = "Guia do Modo Dream Discovery",
  str_n12_entrust_stage_intro_head_1 = "Palco desbloqueado",
  str_n12_entrust_stage_intro_head_2 = "Concluir Estágio",
  str_n12_entrust_stage_intro_head_3 = "Recomp. do Estágio",
  str_n12_entrust_stage_intro_body_1 = "1. Durante o evento, um estágio é desbloqueado todos os dias. Complete a etapa anterior para prosseguir.",
  str_n12_entrust_stage_intro_body_2 = "1. Um estágio é concluído quando você atinge seu ponto final. Após a conclusão, você pode ficar para terminar outros eventos ou sair do palco.",
  str_n12_entrust_stage_intro_body_3 = "1. Ganhe materiais de atualização Lumamber, Nightium e Aurorian ao chegar ao ponto final de cada estágio e baús.",
  str_n12_challenge_diff = "Nível de dificuldade",
  str_n12_challenge_diff_desc = "(Cada nível de dificuldade tem uma pontuação base)",
  str_n12_affix_effect = "Bônus de entrada",
  str_n12_affix_effect_desc = "(Cada entrada concede pontos de bônus)",
  str_n12_battle_cur_score = "Sua pontuação",
  str_n12_battle_record_max = "Melhor pontuação",
